target.css:
:root {
  --paper: #fffdf7;
  --ink: #233044;
  --muted: #697386;
  --line: #d9dde4;
  --blue: #4d79ff;
  --coral: #fb6d5b;
  --cream: #fff3c5;
}

.print-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

.card-header,
.ink-row,
.card-footer {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.title-block h1,
.eyebrow,
.row-label,
.job-label,
.job-value,
.pickup-note {
  margin: 0;
}

.eyebrow,
.row-label,
.job-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.title-block h1 {
  margin-top: 4px;
  font-size: 22px;
  line-height: 1.1;
}

.run-badge {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--cream);
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.ink-row {
  justify-content: space-between;
  padding: 12px 0;
}

.swatches {
  display: flex;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.swatch {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 600;
}

.swatch::before {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  content: "";
}

.swatch.blue::before {
  background: var(--blue);
}

.swatch.coral::before {
  background: var(--coral);
}

.job-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.job-item {
  padding: 10px 12px;
}

.job-item:nth-child(odd) {
  border-right: 1px solid var(--line);
}

.job-item:nth-child(-n + 2) {
  border-bottom: 1px solid var(--line);
}

.job-value {
  margin-top: 3px;
  font-size: 13px;
  font-weight: 600;
}

.card-footer {
  justify-content: space-between;
  padding-top: 14px;
}

.pickup-note {
  color: var(--muted);
  font-size: 12px;
}

.pickup-note strong {
  color: var(--ink);
}

.print-card button {
  border: 0;
  border-radius: 7px;
  padding: 8px 11px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
